package io.github.diodeme.ji.extension;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Comparator;
import java.util.HexFormat;
import java.util.List;

/** Deterministic fingerprints for the complete protected project resource set. */
public final class ResourceFingerprints {
    private ResourceFingerprints() {}

    public static ProjectTrustStore.ProjectFingerprint project(List<ResourceSource.Discovery> discoveries) {
        MessageDigest digest = sha256();
        discoveries.stream()
                .map(ResourceSource.Discovery::descriptor)
                .filter(ResourceDescriptor::requiresProjectTrust)
                .sorted(Comparator.comparing(value -> value.id().value()))
                .forEach(value -> update(digest, value.id().value() + "\0" + value.source().value() + "\0"
                        + value.revision().sourceRevision() + "\0" + value.revision().contentSha256() + "\n"));
        return new ProjectTrustStore.ProjectFingerprint(HexFormat.of().formatHex(digest.digest()));
    }

    public static String sha256(byte[] content) {
        return HexFormat.of().formatHex(sha256().digest(content));
    }

    public static String stableId(String value) {
        return sha256(value.getBytes(StandardCharsets.UTF_8));
    }

    private static void update(MessageDigest digest, String value) {
        digest.update(value.getBytes(StandardCharsets.UTF_8));
    }

    private static MessageDigest sha256() {
        try {
            return MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException impossible) {
            throw new IllegalStateException(impossible);
        }
    }
}
